            \"label\": \"Normal\"\n                  },\n                  {\n                    \"concept\": \"e3c234a6-be97-4b6d-90af-c790c02e591d\",\n                    \"label\": \"Severe Hypothermia\"\n                  }\n                ]\n              },\n              \"id\": \"status\",\n              \"label\": \"Status\",\n              \"questionInfo\": \"Hypothermia (<35.5 oC = severe hypothermia, 35.5 ? 36.5 oC hypothermia, 37.5 oC = fever)\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"PSBI/LBI/NBI\",\n      \"sections\": [\n        {\n          \"label\": \"PSBI/LBI/NBI\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"561b8124-f0df-4db9-bae0-3446335c8269\",\n                \"answers\": [\n                  {\n                    \"concept\": \"f61602a4-7b1e-44b9-8203-bb7ab4ae38b8\",\n                    \"label\": \"Convulsion\"\n                  },\n                  {\n                    \"concept\": \"0e7edada-3fad-4e7b-a3c8-538d6d7d786c\",\n                    \"label\": \"Severe chest indrawing\"\n                  },\n                  {\n                    \"concept\": \"431df7dc-9e22-4f47-a92f-bd9be838c788\",\n                    \"label\": \"Grunting\"\n                  },\n                  {\n                    \"concept\": \"710f3e02-48fc-4f91-b86a-610943cfc5fb\",\n                    \"label\": \"Bulging fontanelle\"\n                  },\n                  {\n                    \"concept\": \"a78a9058-340e-4da3-87fc-e97f2af9456d\",\n                    \"label\": \"Lethargic/ Unconscious\"\n                  },\n                  {\n                    \"concept\": \"29a3eaaa-10d2-4fcd-9b29-16c283164df8\",\n                    \"label\": \"Unable To Feed\"\n                  },\n                  {\n                    \"concept\": \"f687852a-8923-4e02-b7d0-fb2b12c6738d\",\n                    \"label\": \"Not present\"\n                  }\n                ]\n              },\n              \"id\": \"symptoms\",\n              \"label\": \"Symptoms\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"f0fc58f6-5b44-4412-b61f-ddb5302bbe79\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  },\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  }\n                ]\n              },\n              \"id\": \"psbi\",\n              \"label\": \"PSBI\",\n              \"questionInfo\": \"Convulsion, fast breathing 60 or more/Min, severe chest in-drawing, nasal flaring, grunting, unable to suck/swallow breast milk, budging fontanelle, umbilical infection Extending to the surrounding skin, fever >37.5 oC or severe hypothermia <35.5 oC, Pustular lesion (10 or more in number or single large skin pustule), lethargic or unconscious or less than normal body movements\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"b4d0ba0c-47b9-4bb7-bf95-27e6030d5793\",\n                \"answers\": [\n                  {\n                    \"concept\": \"a626ee8c-2b44-43cb-917c-c0d81c01c897\",\n                    \"label\": \"Umbilicus red\"\n                  },\n                  {\n                    \"concept\": \"f5fc5438-2d5f-4ba7-af89-a1e8a926967e\",\n                    \"label\": \"Umbilicus with pus\"\n                  },\n                  {\n                    \"concept\": \"f687852a-8923-4e02-b7d0-fb2b12c6738d\",\n                    \"label\": \"Not present\"\n                  }\n                ]\n              },\n              \"id\": \"umbilicusInfection\",\n              \"label\": \"Umbilicus Infection\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"53cdd43d-67a7-47ae-8e49-98ce6f0235fb\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  },\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  }\n                ]\n              },\n              \"id\": \"lbi\",\n              \"label\": \"LBI\",\n              \"questionInfo\": \"Red umbilicus, or pus discharge from umbilicus; less than 10 pustular skin lesions, eye discharge\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"d22415c7-c97d-4e49-8313-646b6c2e1c0c\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  },\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  }\n                ]\n              },\n              \"id\": \"nbi\",\n              \"label\": \"NBI\",\n              \"questionInfo\": \"No signs and symptoms of infection present\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"5a51d680-d86e-456b-a84c-b78fd2f6a5ef\",\n                \"answers\": [\n                  {\n                    \"concept\": \"8b1d5ba9-51ec-4999-85fc-4d6a21fb9db8\",\n                    \"label\": \"Jaundice present\"\n                  },\n                  {\n                    \"concept\": \"ab4c88ec-fc3c-47c3-92b1-8d0e21c2ba65\",\n                    \"label\": \"Severe Jaundice\"\n                  },\n                  {\n                    \"concept\": \"f687852a-8923-4e02-b7d0-fb2b12c6738d\",\n                    \"label\": \"Not present\"\n                  }\n                ]\n              },\n              \"id\": \"jaundiceStatus\",\n              \"label\": \"Jaundice status\",\n              \"questionInfo\": \"Severe jaundice- (Jaundice extending up to hands and feet, Jaundice seen in first 24 hours or after 14th day of birth), Jaundice (absence of spreading of jaundice up to hands and feet, Jaundice seen in between 2 ? 14 days)\"\n            }\n          ]\n        }\n      ]\n    },\n    {\n      \"label\": \"Diarrhoea Symptoms & Management\",\n      \"sections\": [\n        {\n          \"label\": \"Diarrhoea\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"464a8669-63a1-4f1c-8af3-7db92c7c792b\",\n                \"answers\": [\n                  {\n                    \"concept\": \"e8e92a6b-a3ab-4a05-92a9-2eea8a6fa3c6\",\n                    \"label\": \"Diarrhea\"\n                  },\n                  {\n                    \"concept\": \"a588c9e3-56cb-45dc-9649-4bb6f7a832fd\",\n                    \"label\": \"Chronic Diarrhea\"\n                  },\n                  {\n                    \"concept\": \"6d48a12e-85af-4498-8a52-0d937fd43c25\",\n                    \"label\": \"Diarrhea - Dysentery\"\n                  },\n                  {\n                    \"concept\": \"f687852a-8923-4e02-b7d0-fb2b12c6738d\",\n                    \"label\": \"Not present\"\n                  }\n                ]\n              },\n              \"id\": \"diarrhoeaPresent\",\n              \"label\": \"Diarrhoea present\",\n              \"questionInfo\": \"watery stool three times or more in 24 hours, Dysentery: Presence of blood in the stool, Chronic Diarrhoea - Diarrhoea for more than 14 days\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"13bbd0a1-9a2a-4cec-9b08-da9491cc785d\",\n                \"answers\": [\n                  {\n                    \"concept\": \"e822c515-f840-4ff0-bed9-a803a7542802\",\n                    \"label\": \"Some Dehydration\"\n                  },\n                  {\n                    \"concept\": \"69d419df-d5ed-41e1-9abe-c698be74ecc7\",\n                    \"label\": \"Severe Dehydration\"\n                  },\n                  {\n                    \"concept\": \"8110a92e-2eb6-4074-9d71-afc39d908721\",\n                    \"label\": \"No Dehydration\"\n                  },\n                  {\n                    \"concept\": \"1175AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Not applicable\"\n                  }\n                ]\n              },\n              \"id\": \"dehydrationStatus\",\n              \"label\": \"Dehydration Status\",\n              \"questionInfo\": \"Severe Dehydration (If any of two given signs present) Lethargic or unconscious Body movement less than normal Sunken eyes Skin pinch goes back very slowly (>2 seconds) Infant less than one month of age Some dehydration: Irritable Sunken eyes Skin pinch goes back slowly (<2 seconds) No Dehydration: No sufficient signs to classify under severe or some dehydration\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"aeff1ac5-67a9-4ce6-89c0-3692835f241e\",\n                \"answers\": [\n                  {\n                    \"concept\": \"f4d3c9bb-b39a-4f12-9154-270ed2018b0e\",\n                    \"label\": \"Slowly\"\n                  },\n                  {\n                    \"concept\": \"c557490d-5d52-4717-a608-e54b464cb439\",\n                    \"label\": \"Very Slowly\"\n                  }\n                ]\n              },\n              \"id\": \"skinPinch\",\n              \"label\": \"Skin pinch\",\n              \"hide\": {\n                \"hideWhenExpression\": \"isEmpty(dehydrationStatus) || (dehydrationStatus == \'1175AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\')\"\n              }\n            }\n          ]\n        },\n        {\n          \"label\": \" Low weight/ Feeding Problem\",\n          \"isExpanded\": \"true\",\n          \"questions\": [\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"radio\",\n                \"concept\": \"9cf32a21-631e-4f8c-8d53-4db6b3ad46dc\",\n                \"answers\": [\n                  {\n                    \"concept\": \"1065AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"Yes\"\n                  },\n                  {\n                    \"concept\": \"1066AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\",\n                    \"label\": \"No\"\n                  }\n                ]\n              },\n              \"id\": \"breastfeed\",\n              \"label\": \"Breast Feed\"\n            },\n            {\n              \"type\": \"obs\",\n              \"questionOptions\": {\n                \"rendering\": \"number\",\n                \"concept\": \"5870aac0-15b1-4b4c-8cc4-7b88c6967910\"\n              },\n              \"id\": \"breastFeeding,HowManyTimesIn24Hours?\",\n              \"label\": \"Breast feeding, How many times in 24 hours?\",\n              \"hide\": {\n    