(13,19,'A convenience set for billable services','en',2,'2026-10-14 12:12:38',NULL,NULL,'abf1c018-f18a-5371-8ad4-8596ecc8327f'),
(14,20,'A species of parasitic nematode that is the largest found in the human intestine. Its distribution is worldwide, but it is more prevalent in areas of poor sanitation. Human infection with A. lumbricoides is acquired by swallowing fully embryonated eggs from contaminated soil.','en',2,'2026-10-14 12:12:38',NULL,NULL,'11475FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(15,21,'Infection with any of various amebae. It is an asymptomatic carrier state in most individuals, but diseases ranging from chronic, mild diarrhea to fulminant dysentery may occur.','en',2,'2026-10-14 12:12:38',NULL,NULL,'11388FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(17,24,'A species of trematode blood flukes of the family Schistosomatidae. It is common in the Nile delta. The intermediate host is the planorbid snail. This parasite causes schistosomiasis mansoni and intestinal bilharziasis.','en',2,'2026-10-14 12:12:39',NULL,NULL,'8165FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(20,27,'Peripheral smear study for malarial parasites is the gold standard in diagnosing malarial infection. It involves collection of a blood smear, staining and examination of the the red blood cells for intracellular malarial parasites.','en',2,'2026-10-14 12:12:39',NULL,NULL,'33FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(21,28,'Evaluation of stool under a microscope, usually for ova and parasites.','en',2,'2026-10-14 12:12:39',NULL,NULL,'305FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(23,30,'A subclass of segmented worms comprising the tapeworms.','en',2,'2026-10-14 12:12:39',NULL,NULL,'6159FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(24,32,'Descriptive term: not precisely defined, determinable, or established.','en',2,'2026-10-14 12:12:40',NULL,NULL,'1141FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(28,37,'A genus of nematode intestinal parasites that consists of several species. A. duodenale is the common hookworm in humans. A. braziliense, A. ceylonicum, and A. caninum occur primarily in cats and dogs, but all have been known to occur in humans.','en',2,'2026-10-14 12:12:40',NULL,NULL,'15166FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(29,38,'An intentional relinquishment of some rights for example the claim of a bill against the cost of a service or commodity','en',2,'2026-10-14 12:12:40',NULL,NULL,'980FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
