INSERT INTO `global_property` VALUES
('@openmrs/esm-fast-data-entry-app.groupSessionVisitTypeUuid','78370d15-38ad-48a1-825f-f0e9ff60d5a1','UUID of the visit type used by Fast Data Entry to create visits when in \'group sessions\' entry workflow','a499d6f6-a582-4631-9551-1df71a9940fe',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.addressToEntryMapUpdaterLastStartTime',NULL,'The module uses this field to store when the AddressToEntryMapUpdater task was last started; DO NOT MODIFY','17830eef-d7fa-40c3-8c75-38a342e65f2d',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.allowFreetext','true','Valid values: true/false. When overriding the address portlet, allow the entry of free text for address fields associated with the address hierarchy by providing an \"Other\" option','f8ae4ed9-ff2f-4746-97f8-0ead046399db',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.enableOverrideOfAddressPortlet','true','Valid values: true/false. When enabled, the existing \"edit\" component of the address portlet is overridden by the new functionality provided by the address hierarchy module','f70e1f3e-f40e-4720-bfd8-03a9e67a4dc3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.initializeAddressHierarchyCacheOnStartup','true','Sets whether to initialize the address hierarchy in-memory cache (which is used to speed up address hierarchy searches.\nGenerally, you want to set this to \"true\", though developers may want to set it to false during development\nto speed module start-up.','b50452e7-b8f4-4dd3-9ff9-c1a97db026b3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
