('patient_identifier.importantTypes',NULL,'A comma delimited list of PatientIdentifier names : PatientIdentifier locations that will be displayed on the patient dashboard.  E.g.: TRACnet ID:Rwanda,ELDID:Kenya','782440dd-ab92-4c9b-aa5e-28a9734917a3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('patient.defaultPatientIdentifierValidator','org.openmrs.patient.impl.LuhnIdentifierValidator','This property sets the default patient identifier validator.  The default validator is only used in a handful of (mostly legacy) instances.  For example, it\'s used to generate the isValidCheckDigit calculated column and to append the string \"(default)\" to the name of the default validator on the editPatientIdentifierType form.','04762247-6d55-48d3-a2ad-36b40b29035e',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('patient.headerAttributeTypes',NULL,'A comma delimited list of PersonAttributeType names that will be shown on the patient dashboard','4609457a-9d21-4ec2-80ce-c83a200cbd00',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('patient.identifierPrefix',NULL,'This property is only used if patient.identifierRegex is empty.  The string here is prepended to the sql indentifier search string.  The sql becomes \"... where identifier like \'<PREFIX><QUERY STRING><SUFFIX>\';\".  Typically this value is either a percent sign (%) or empty.','8d9239b3-06d1-465a-aae1-da73018bb9db',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('patient.identifierRegex',NULL,'WARNING: Using this search property can cause a drop in mysql performance with large patient sets.  A MySQL regular expression for the patient identifier search strings.  The @SEARCH@ string is replaced at runtime with the user\'s search string.  An empty regex will cause a simply \'like\' sql search to be used. Example: ^0*@SEARCH@([A-Z]+-[0-9])?$','a62944ef-6a15-42f6-9257-f99fb2c8c0ad',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('patient.identifierSearchPattern',NULL,'If this is empty, the regex or suffix/prefix search is used.  Comma separated list of identifiers to check.  Allows for faster searching of multiple options rather than the slow regex. e.g. @SEARCH@,0@SEARCH@,@SEARCH-1@-@CHECKDIGIT@,0@SEARCH-1@-@CHECKDIGIT@ would turn a request for \"4127\" into a search for \"in (\'4127\',\'04127\',\'412-7\',\'0412-7\')\"','b1489289-c8be-4235-b219-09e81ffbe7b1',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('patient.identifierSuffix',NULL,'This property is only used if patient.identifierRegex is empty.  The string here is prepended to the sql indentifier search string.  The sql becomes \"... where identifier like \'<PREFIX><QUERY STRING><SUFFIX>\';\".  Typically this value is either a percent sign (%) or empty.','6df515d8-297c-437e-94c6-2858c3c955ee',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
