INSERT INTO `serialized_object` VALUES
(1,'Patient Identifier Sticker','','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.report.definition.ReportDefinition id=\"1\" uuid=\"08e2d4eb-91f7-4067-a0c9-025af2122686\" retired=\"false\">\n  <name>Patient Identifier Sticker</name>\n  <description></description>\n  <creator id=\"2\" uuid=\"A4F30A1B-5EB9-11DF-A648-37A07F9C90FB\"/>\n  <dateCreated id=\"3\">2026-10-14 12:43:45 UTC</dateCreated>\n  <parameters id=\"4\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"5\">\n      <name>patientUuid</name>\n      <label>Patient UUID</label>\n      <type>java.lang.String</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n  <dataSetDefinitions class=\"linked-hash-map\" id=\"6\">\n    <entry>\n      <string>fields</string>\n      <org.openmrs.module.reporting.evaluation.parameter.Mapped id=\"7\">\n        <parameterizable class=\"org.openmrs.module.patientdocuments.library.PatientIdStickerDataSetDefinition\" id=\"8\" retired=\"false\">\n          <parameters reference=\"4\"/>\n        </parameterizable>\n        <parameterMappings id=\"9\">\n          <entry>\n            <string>patientUuid</string>\n            <string>${patientUuid}</string>\n          </entry>\n        </parameterMappings>\n      </org.openmrs.module.reporting.evaluation.parameter.Mapped>\n    </entry>\n  </dataSetDefinitions>\n</org.openmrs.module.reporting.report.definition.ReportDefinition>','2026-10-14 12:43:45',2,NULL,NULL,0,NULL,NULL,NULL,'08e2d4eb-91f7-4067-a0c9-025af2122686'),
(2,'Generic Encounter PDF Report','Dynamically generates PDF printouts for one or more clinical encounters based on O3 forms.','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.report.definition.ReportDefinition','org.openmrs.module.reporting.serializer.ReportingSerializer','<org.openmrs.module.reporting.report.definition.ReportDefinition id=\"1\" uuid=\"0e89ec4c-10bb-11f1-a6da-0242ac1e0002\" retired=\"false\">\n  <name>Generic Encounter PDF Report</name>\n  <description>Dynamically generates PDF printouts for one or more clinical encounters based on O3 forms.</description>\n  <creator id=\"2\" uuid=\"A4F30A1B-5EB9-11DF-A648-37A07F9C90FB\"/>\n  <dateCreated id=\"3\">2026-10-14 12:43:45 UTC</dateCreated>\n  <parameters id=\"4\">\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"5\">\n      <name>encounterUuids</name>\n      <label>Encounter UUIDs (comma separated)</label>\n      <type>java.lang.String</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n    <org.openmrs.module.reporting.evaluation.parameter.Parameter id=\"6\">\n      <name>locale</name>\n      <label>Locale</label>\n      <type>java.util.Locale</type>\n      <required>true</required>\n    </org.openmrs.module.reporting.evaluation.parameter.Parameter>\n  </parameters>\n</org.openmrs.module.reporting.report.definition.ReportDefinition>','2026-10-14 12:43:45',2,NULL,NULL,0,NULL,NULL,NULL,'0e89ec4c-10bb-11f1-a6da-0242ac1e0002');
